import{_ as a,o as i,c as l,ae as t}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"WEBSITE.md","description":"","frontmatter":{},"headers":[],"relativePath":"WEBSITE.md","filePath":"WEBSITE.md"}'),r={name:"WEBSITE.md"};function o(n,e,s,u,h,c){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="website-md" tabindex="-1">WEBSITE.md <a class="header-anchor" href="#website-md" aria-label="Permalink to &quot;WEBSITE.md&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>The website presents a structured body of work while:</p><ul><li>signalling rigor and coherence</li><li>avoiding commercial or product framing</li><li>preserving intellectual property through selective disclosure</li></ul><hr><h2 id="current-state" tabindex="-1">Current state <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current state&quot;">​</a></h2><p>The site currently includes:</p><ul><li>AI metascientist (method)</li><li>GRID+ (framework)</li><li>AVA (tool)</li><li>homepage</li></ul><p>The structure is intentionally minimal and will expand incrementally.</p><hr><h2 id="site-identity" tabindex="-1">Site identity <a class="header-anchor" href="#site-identity" aria-label="Permalink to &quot;Site identity&quot;">​</a></h2><p>Title: research systems</p><p>Subtitle: methods for knowledge and evaluation</p><p>Byline: Hélène Draux</p><hr><h2 id="site-structure" tabindex="-1">Site structure <a class="header-anchor" href="#site-structure" aria-label="Permalink to &quot;Site structure&quot;">​</a></h2><p>Top-level routes:</p><ul><li>/</li><li>/methods/</li><li>/frameworks/</li><li>/tools/</li><li>/notes/ (optional)</li><li>/about/</li></ul><hr><h2 id="core-navigation-model" tabindex="-1">Core navigation model <a class="header-anchor" href="#core-navigation-model" aria-label="Permalink to &quot;Core navigation model&quot;">​</a></h2><p>The site is organised into three explicit layers:</p><ul><li>Methods → conceptual</li><li>Frameworks → applied</li><li>Tools → operational</li></ul><p>Hierarchy must be preserved: methods &gt; frameworks &gt; tools</p><hr><h2 id="homepage-structure" tabindex="-1">Homepage structure <a class="header-anchor" href="#homepage-structure" aria-label="Permalink to &quot;Homepage structure&quot;">​</a></h2><h3 id="header" tabindex="-1">Header <a class="header-anchor" href="#header" aria-label="Permalink to &quot;Header&quot;">​</a></h3><ul><li>title</li><li>subtitle</li><li>byline</li></ul><h3 id="intro" tabindex="-1">Intro <a class="header-anchor" href="#intro" aria-label="Permalink to &quot;Intro&quot;">​</a></h3><p>Neutral description of activity:</p><ul><li>describing, structuring, evaluating research systems</li><li>focus on knowledge representation and analysis</li><li>mention AI evaluation context</li></ul><p>Constraint:</p><ul><li>must not read as an introduction or pitch</li><li>must reflect structure rather than explain intent</li><li>must avoid “platform” or “project” framing</li></ul><hr><h3 id="three-layers-section" tabindex="-1">Three layers section <a class="header-anchor" href="#three-layers-section" aria-label="Permalink to &quot;Three layers section&quot;">​</a></h3><p>Methods<br> Conceptual approaches for representing and analysing the structure of research systems</p><p>Frameworks<br> Structured applications of methods in defined analytical contexts</p><p>Tools<br> Lightweight implementations supporting specific analytical tasks</p><hr><h3 id="current-work" tabindex="-1">Current work <a class="header-anchor" href="#current-work" aria-label="Permalink to &quot;Current work&quot;">​</a></h3><ul><li>AI metascientist (method)</li><li>GRID+ (framework)</li><li>AVA (tool)</li></ul><hr><h3 id="perspective" tabindex="-1">Perspective <a class="header-anchor" href="#perspective" aria-label="Permalink to &quot;Perspective&quot;">​</a></h3><ul><li>positioned within bibliometrics and research systems analysis</li><li>increasing focus on evaluation under automation</li><li>selective disclosure of full implementation</li></ul><hr><h3 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h3><p>Methods → Frameworks → Tools<br> Conceptual → Applied → Operational</p><p>Methods inform frameworks.<br> Frameworks organise tools.</p><hr><h2 id="page-templates" tabindex="-1">Page templates <a class="header-anchor" href="#page-templates" aria-label="Permalink to &quot;Page templates&quot;">​</a></h2><h3 id="method-page" tabindex="-1">Method page <a class="header-anchor" href="#method-page" aria-label="Permalink to &quot;Method page&quot;">​</a></h3><ul><li>conceptual definition</li><li>structured explanation</li><li>no implementation detail</li></ul><h3 id="framework-page" tabindex="-1">Framework page <a class="header-anchor" href="#framework-page" aria-label="Permalink to &quot;Framework page&quot;">​</a></h3><ul><li>structured system</li><li>partial example</li><li>no full scoring logic</li></ul><h3 id="tool-page" tabindex="-1">Tool page <a class="header-anchor" href="#tool-page" aria-label="Permalink to &quot;Tool page&quot;">​</a></h3><ul><li>constrained functionality</li><li>example usage</li><li>no internal logic</li></ul><hr><h2 id="coherence-constraint" tabindex="-1">Coherence constraint <a class="header-anchor" href="#coherence-constraint" aria-label="Permalink to &quot;Coherence constraint&quot;">​</a></h2><p>Pages must align across layers:</p><ul><li>methods define concepts used by frameworks</li><li>frameworks structure logic used by tools</li><li>tools reference frameworks, not define them</li></ul><p>Each page must clearly belong to one layer.</p><hr><h2 id="depth-signalling" tabindex="-1">Depth signalling <a class="header-anchor" href="#depth-signalling" aria-label="Permalink to &quot;Depth signalling&quot;">​</a></h2><p>Each page should indicate:</p><ul><li>overview: available</li><li>methodological detail: partial</li><li>full protocol and implementation: not public</li></ul><hr><h2 id="visual-design-principles" tabindex="-1">Visual design principles <a class="header-anchor" href="#visual-design-principles" aria-label="Permalink to &quot;Visual design principles&quot;">​</a></h2><p>Typography:</p><ul><li>serif primary</li><li>restrained sans-serif for UI</li></ul><p>Layout:</p><ul><li>moderate density</li><li>left-aligned</li><li>no visual noise</li></ul><p>Color:</p><ul><li>off-white background</li><li>near-black text</li><li>muted accent</li></ul><hr><h2 id="what-to-avoid" tabindex="-1">What to avoid <a class="header-anchor" href="#what-to-avoid" aria-label="Permalink to &quot;What to avoid&quot;">​</a></h2><ul><li>gradients</li><li>animations</li><li>hero sections</li><li>product UI patterns</li><li>marketing language</li><li>calls-to-action</li></ul><hr><h2 id="iteration-approach" tabindex="-1">Iteration approach <a class="header-anchor" href="#iteration-approach" aria-label="Permalink to &quot;Iteration approach&quot;">​</a></h2><p>The site is developed incrementally:</p><ul><li>add one page at a time</li><li>maintain consistency with existing pages</li><li>avoid expanding multiple sections simultaneously</li></ul><p>After each addition:</p><ul><li>review coherence across pages</li><li>adjust structure if needed</li></ul><hr><h2 id="implementation-notes" tabindex="-1">Implementation notes <a class="header-anchor" href="#implementation-notes" aria-label="Permalink to &quot;Implementation notes&quot;">​</a></h2><p>Stack:</p><ul><li>VitePress (content)</li><li>Vite (tools if needed)</li><li>Cloudflare Pages (hosting)</li></ul><hr><h2 id="guiding-principle" tabindex="-1">Guiding principle <a class="header-anchor" href="#guiding-principle" aria-label="Permalink to &quot;Guiding principle&quot;">​</a></h2><p>The site should read as:</p><ul><li>a system of methods<br> not</li><li>a collection of products</li></ul><p>And:</p><ul><li>complete at the conceptual level</li><li>intentionally bounded at the operational level</li></ul>',91)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
